<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:650px;margin:0 auto;"><div class="card-header"><h1>Store Visit Request</h1><p>Request a visit to a seller's store.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<form method="post" action="<?php echo e(url_for('customer','visit'));?>"><?php echo csrf_field();?><div class="field"><label>Seller</label><select name="seller_id"><option value="">Select a seller...</option><?php foreach($sellers as $s):$label=$s['shop_name']?$s['shop_name'].' ('.$s['name'].')':$s['name'];?><option value="<?php echo e($s['id']);?>" <?php echo $seller_id===(string)$s['id']?'selected':'';?>><?php echo e($label);?></option><?php endforeach;?></select></div><div class="field"><label>Visit Date</label><input type="date" name="visit_date" value="<?php echo e($visit_date);?>"></div><div class="field"><label>Message</label><textarea name="message" rows="2"><?php echo e($message);?></textarea></div><button class="btn btn-primary btn-block">Send Request</button></form></div>
<div class="card"><div class="card-header"><h2>Your Requests</h2></div><?php if(!$my_visits):?><p class="muted">No requests yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Seller</th><th>Date</th><th>Message</th><th>Status</th><th>Sent</th></tr><?php foreach($my_visits as $v):?><tr><td>#<?php echo e($v['id']);?></td><td><?php echo e($v['seller_name']);?><?php echo $v['shop_name']?' ('.e($v['shop_name']).')':'';?></td><td><?php echo e($v['visit_date']);?></td><td><?php echo $v['message']?e($v['message']):'—';?></td><td><?php echo e($v['status']);?></td><td class="small"><?php echo e($v['created_at']);?></td></tr><?php endforeach;?></table><?php endif;?></div>
